/bin/bash -lc "curl -L --fail --silent 'https://gtexportal.org/api/v2/dataset/fileList?datasetId=gtex_v8' | python3 -c 'import json,sys; d=json.load(sys.stdin); 
for v in d:
  for fs in v.get(\"filesets\",[]):
    for f in fs.get(\"files\",[]):
      if \"brain_cortex\" in f.get(\"name\",\"\") or \"gene_median_tpm\" in f.get(\"name\",\"\"):
        print(json.dumps({\"version\":v.get(\"id\"),\"fileset\":fs.get(\"subpath\"),\"file\":f}, sort_keys=True))'"

/bin/bash -lc "curl -L --fail --silent 'https://storage.googleapis.com/storage/v1/b/adult-gtex/o?prefix=bulk-gex/v8/rna-seq/tpms-by-tissue/&maxResults=1000' | python3 -c 'import json,sys; d=json.load(sys.stdin); 
for x in d.get(\"items\",[]):
 n=x.get(\"name\",\"\");
 if \"brain_cortex\" in n or \"median\" in n: print(n, x.get(\"size\"), x.get(\"md5Hash\"))'"
